"""Rebuild learning presentation from the source-bound pre-redesign articles."""
from pathlib import Path
import re, json, html, subprocess
ROOT = Path(__file__).resolve().parents[1]
BASE = '67b9b1e494e9e21d954a2b6eb1b357c91c151853'
def old(name): return subprocess.check_output(['git','show',BASE+':'+name],cwd=ROOT,text=True)
def plain(s): return ' '.join(re.sub('<[^>]+>',' ',html.unescape(s)).split())
shell=old('priyomnaya.html')
header=shell[shell.index('<body'):shell.index('<main')]
header=re.sub(r'<body[^>]*>','<body class="salon-direct salon-experience concept-shell salon-learning">',header)
